const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { digest: 'No new emails found for today.', email_count: 0 } }];
}

const skipPatterns = [
  /job alert/i,
  /jobs across/i,
  /looking for job/i,
  /linkedin job/i,
  /jobalerts/i,
  /pakistan ki jobs/i,
  /reshare jobs/i,
  /hrpp updates/i,
  /recruitment:/i,
  /people, policy/i,
  /skool\.com/i,
  /notification since/i
];

const urgent = [];
const newsletters = [];
const other = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;

  const from = item.From || item.from || 'Unknown sender';
  const subject = item.Subject || item.subject || 'No subject';
  const snippet = (item.snippet || '')
    .replace(/͏/g, '')
    .replace(/\s{2,}/g, ' ')
    .replace(/\n+/g, ' ')
    .trim()
    .substring(0, 200);

  const shouldSkip = skipPatterns.some(p =>
    p.test(subject) || p.test(from)
  );
  if (shouldSkip) continue;

  const entry = `From: ${from}\nSubject: ${subject}\nPreview: ${snippet}`;

  if (/warning|past due|invoice|action required|deprovisioned|deleted/i.test(subject + snippet)) {
    urgent.push(entry);
  } else if (/newsletter|weekly|digest|insights|dispatch|update/i.test(subject + from)) {
    newsletters.push(entry);
  } else {
    other.push(entry);
  }
}

const sections = [];
if (urgent.length > 0) sections.push('=== URGENT ===\n' + urgent.join('\n\n'));
if (newsletters.length > 0) sections.push('=== NEWSLETTERS ===\n' + newsletters.join('\n\n'));
if (other.length > 0) sections.push('=== OTHER ===\n' + other.join('\n\n'));

const digest = sections.length > 0
  ? sections.join('\n\n')
  : 'No significant emails found today.';

return [{ json: { digest, email_count: items.length } }];

const text = $input.first().json.output || '';

// 3500 chars ≈ 500 words, safely under Smallest AI 8000 char limit
const MAX_CHARS = 3500;

const truncated = text.length > MAX_CHARS
  ? text.substring(0, MAX_CHARS).replace(/\s+\S*$/, '') + '...'
  : text;

return [{ json: { tts_text: truncated } }];
